function solve(capacity, keys) {
  const recent = [];
  const out = [];
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const at = recent.indexOf(key);
    if (at !== -1) {
      recent.splice(at, 1);
      recent.unshift(key);
      out.push(1);
    } else {
      recent.unshift(key);
      if (recent.length > capacity) recent.pop();
      out.push(0);
    }
  }
  return out;
}

function solve(capacity, keys) {
  const nodes = new Map();
  let head = null;
  let tail = null;
  const out = [];
  const placeAtFront = (node) => {
    node.prev = null;
    node.next = head;
    if (head) head.prev = node;
    head = node;
    if (!tail) tail = node;
  };
  const unlink = (node) => {
    if (node.prev) node.prev.next = node.next;
    else head = node.next;
    if (node.next) node.next.prev = node.prev;
    else tail = node.prev;
    node.prev = null;
    node.next = null;
  };
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    const node = nodes.get(key);
    if (node) {
      unlink(node);
      placeAtFront(node);
      out.push(1);
    } else {
      const fresh = { key: key, prev: null, next: null };
      nodes.set(key, fresh);
      placeAtFront(fresh);
      if (nodes.size > capacity) {
        const victim = tail;
        unlink(victim);
        nodes.delete(victim.key);
      }
      out.push(0);
    }
  }
  return out;
}
